function Sha([string]$Path){$stream=[IO.File]::OpenRead($Path);$hash=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($hash.ComputeHash($stream))).Replace('-','').ToLowerInvariant()}finally{$stream.Dispose();$hash.Dispose()}}
function SafeError([object]$Value){$text=[string]$Value;$text=$text-replace'(?i)(?:Bearer|Basic)\s+\S+','[credential redacted]';$text=$text-replace'(?i)\b(?:password|passwd|pwd|credential|token|secret|api[_ -]?key|authorization|bearer|密码|口令|凭据|账号|登录)\s*[:=]\s*\S+','[credential redacted]';$text=$text-replace'[\r\n]+','_';if($text.Length-gt500){$text=$text.Substring(0,500)};$text}
function WriteJson([string]$Path,[object]$Value){$tmp="$Path.$PID.tmp";[IO.File]::WriteAllText($tmp,(($Value|ConvertTo-Json -Depth 40)+"`n"),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $tmp -Destination $Path -Force}
function ReadObj([string]$Path,[string]$Code){if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw "$Code`:MISSING"};try{$v=Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}catch{throw "$Code`:INVALID_JSON"};if($null-eq$v-or$v-is[array]){throw "$Code`:OBJECT_REQUIRED"};$v}
function Tree([string]$Path){$full=[IO.Path]::GetFullPath($Path).TrimEnd('\');$rows=@(Get-ChildItem -LiteralPath $full -Recurse -File -Force|Where-Object{$_.Name-notmatch'\.(pyc|pyo)$'-and$_.FullName-notmatch'[\\/]__pycache__[\\/]'}|Sort-Object FullName|ForEach-Object{"$($_.FullName.Substring($full.Length).TrimStart('\').Replace('\','/'))|$([long]$_.Length)|$(Sha $_.FullName)"});$h=[Security.Cryptography.SHA256]::Create();try{$d=([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes(($rows-join"`n"))))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};[ordered]@{file_count=$rows.Count;sha256=$d}}
function AssertNoReparse([string]$Path){$i=Get-Item -LiteralPath $Path -Force;if($i.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'R121_REPARSE_REJECTED'};$bad=@(Get-ChildItem -LiteralPath $Path -Recurse -Force|Where-Object{$_.Attributes-band[IO.FileAttributes]::ReparsePoint});if($bad.Count){throw 'R121_REPARSE_REJECTED'}}
function RuntimeInfo{$c=ReadObj (Join-Path $root 'config\node-config.json') 'R121_NODE_CONFIG';$m=ReadObj (Join-Path ([string]$c.web_runtime_root) 'runtime-build-manifest.json') 'R121_WEB_MANIFEST';[ordered]@{config=$c;manifest=$m}}
function Headers{$c=(RuntimeInfo).config;$p=Join-Path ([string]$c.data_root) 'workspace\runtime\runtime.token';if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw 'R121_RUNTIME_TOKEN_MISSING'};$t=(Get-Content -LiteralPath $p -Raw -Encoding ASCII).Trim();if($t-cnotmatch'^[A-Za-z0-9_-]{32,128}$'){throw 'R121_RUNTIME_TOKEN_INVALID'};@{Authorization='Bearer '+$t}}
function Api([string]$Path){Invoke-RestMethod -Method Get -Uri ('http://127.0.0.1:8765'+$Path) -Headers (Headers) -TimeoutSec 30}
function Health([string]$Uri){$rows=@();foreach($n in 1..3){$r=Invoke-WebRequest -Uri $Uri -UseBasicParsing -TimeoutSec 15;$p=$r.Content|ConvertFrom-Json;if([int]$r.StatusCode-ne200-or-not[bool]$p.ok-or[string]$p.status-cne'ready'-or[string]$p.build_id-cne$fixedWebBuild-or@($p.failures).Count-ne0){throw 'R121_HEALTH_REJECTED'};$rows+=[ordered]@{sample=$n;status_code=200;build_id=$fixedWebBuild;exact=$true};if($n-lt3){Start-Sleep -Milliseconds 250}};[ordered]@{status='ready';samples=$rows}}
function Managed{$s=ReadObj (Join-Path $root 'state\node-processes.json') 'R121_NODE_STATE';$roles=[ordered]@{};foreach($role in @('tenant_enrollment_queue','llm_gateway','python_runtime','web')){$r=@($s.records|Where-Object{[string]$_.role-ceq$role});if($r.Count-ne1){throw "R121_ROLE_COUNT:$role"};$p=[int]$r[0].pid;$proc=Get-CimInstance Win32_Process -Filter "ProcessId=$p";$owner=$proc|Invoke-CimMethod -MethodName GetOwner;if([string]$owner.User-cne'EvoMindSvc'){throw "R121_ROLE_OWNER:$role"};$roles[$role]=[ordered]@{pid=$p;owner='EvoMindSvc';name=[string]$proc.Name}};$listeners=[ordered]@{};foreach($port in @(65068,8765,8088,7890)){$rows=@(Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue);if($rows.Count-ne1){throw "R121_LISTENER_COUNT:$port"};$proc=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$rows[0].OwningProcess)";$owner=$proc|Invoke-CimMethod -MethodName GetOwner;if([string]$owner.User-cne'EvoMindSvc'){throw "R121_LISTENER_OWNER:$port"};$listeners[[string]$port]=[ordered]@{pid=[int]$rows[0].OwningProcess;owner='EvoMindSvc';name=[string]$proc.Name}};if(@($roles.Values|ForEach-Object{[int]$_.pid}|Select-Object -Unique).Count-ne4-or@($listeners.Values|ForEach-Object{[int]$_.pid}|Select-Object -Unique).Count-ne4){throw 'R121_MANAGED_PID_DUPLICATE'};[ordered]@{roles=$roles;listeners=$listeners;state_sha256=Sha (Join-Path $root 'state\node-processes.json')}}
function Assert-Fresh([object]$Before,[object]$After){foreach($role in @('tenant_enrollment_queue','llm_gateway','python_runtime','web')){if([int]$Before.roles[$role].pid-eq[int]$After.roles[$role].pid){throw "R121_ROLE_NOT_FRESH:$role"}};foreach($port in @('65068','8765','8088','7890')){if([int]$Before.listeners[$port].pid-eq[int]$After.listeners[$port].pid){throw "R121_LISTENER_NOT_FRESH:$port"}}}
function RunGate{$s=Api "/v1/runs/$fixedRun";$a=@($s.active_tool_calls).Count;$p=@($s.approvals|Where-Object{[string]$_.status-ceq'pending'}).Count;if([string]$s.id-cne$fixedRun-or[string]$s.status-cne'cancelled'-or-not[bool]$s.terminal-or$a-ne0-or$p-ne0){throw 'R121_RUN_GATE_REJECTED'};[ordered]@{run_id=$fixedRun;status='cancelled';terminal=$true;effective_active_count=0;pending_approval_count=0;last_event_seq=if($s.PSObject.Properties.Name-contains'last_event_seq'){[int64]$s.last_event_seq}else{[int64]0}}}
function GoalGate{$g=Api '/v1/goals/goal_g21_five_competition';if([string]$g.run_id-cne$fixedRun-or[string]$g.allocation-cne$fixedAllocation-or[string]$g.status-cne'blocked'-or[string]$g.spec_sha256-cne$goalSpecSha-or[string]$g.board_sha256-cne$goalBoardSha){throw 'R121_GOAL_BINDING_REJECTED'};[ordered]@{id=[string]$g.id;status=[string]$g.status;spec_sha256=[string]$g.spec_sha256;board_sha256=[string]$g.board_sha256;human_baseline_sha256=[string]$g.human_baseline_sha256;updated_at=[string]$g.updated_at}}
function ToolGate{$t=Api '/v1/tools';$r=@($t.tools|Where-Object{[string]$_.name-ceq'hpc_asset_probe'});if($r.Count-ne1-or-not[bool]$r[0].read_only-or[string]$r[0].capability-cne'hpc.read'){throw 'R121_TOOL_GATE_REJECTED'};[ordered]@{name='hpc_asset_probe';read_only=$true;capability='hpc.read'}}
function Boundary{$b=Join-Path $root 'byoa\tenants\tenant_ba0ef9d3767f2fb385b856e0\hpc-binding.json';if(-not(Test-Path -LiteralPath $b -PathType Leaf)){throw 'R121_BINDING_MISSING'};[ordered]@{binding_sha256=Sha $b;byoa_tree=Tree (Join-Path $root 'byoa')}}
function SameBoundary([object]$A,[object]$B){if($A.binding_sha256-cne$B.binding_sha256-or$A.byoa_tree.sha256-cne$B.byoa_tree.sha256){throw 'R121_BOUNDARY_CHANGED'}}
function InvokeManaged([ValidateSet('Stop','Start')][string]$Name){if(-not(Test-Path -LiteralPath $action -PathType Leaf)){throw 'R121_SERVICE_ACTION_MISSING'};$r=@(& $action -Action $Name -TimeoutMinutes 12)|Out-String|ConvertFrom-Json;if([string]$r.status-cne'completed'-or[string]$r.action-cne$Name){throw "R121_MANAGED_$($Name.ToUpperInvariant())_FAILED"};$r}
function AssertStopped{if(@(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue|Where-Object{$_.LocalPort-in@(65068,8765,8088,7890)}).Count){throw 'R121_STOP_LISTENERS_REMAIN'}}
function BackupDb([string]$BackupRoot,[object]$Config){$db=Join-Path ([string]$Config.data_root) 'workspace\runtime\runtime.sqlite3';if(-not(Test-Path -LiteralPath $db -PathType Leaf)){throw 'R121_DB_MISSING'};$d=Join-Path $BackupRoot 'database';New-Item -ItemType Directory -Path $d|Out-Null;$rows=@();foreach($suffix in @('','-wal','-shm')){$src="$db$suffix";$e=Test-Path -LiteralPath $src -PathType Leaf;$row=[ordered]@{suffix=$suffix;existed=$e;bytes=0;sha256=''};if($e){$name=if($suffix){"runtime.sqlite3$suffix"}else{'runtime.sqlite3'};Copy-Item -LiteralPath $src -Destination (Join-Path $d $name);$row.bytes=[long](Get-Item -LiteralPath $src).Length;$row.sha256=Sha $src};$rows+=[pscustomobject]$row};[ordered]@{path=$db;files=$rows}}
function RestoreDb([string]$BackupRoot,[object]$Backup){foreach($suffix in @('','-wal','-shm')){$p="$($Backup.path)$suffix";if(Test-Path -LiteralPath $p){Remove-Item -LiteralPath $p -Force}};foreach($row in @($Backup.files)){if([bool]$row.existed){$name=if([string]$row.suffix){"runtime.sqlite3$([string]$row.suffix)"}else{'runtime.sqlite3'};Copy-Item -LiteralPath (Join-Path (Join-Path $BackupRoot 'database') $name) -Destination "$($Backup.path)$([string]$row.suffix)"}}}
function Inputs{$a=ReadObj $approvalPath 'R121_APPROVAL';if((Sha $approvalPath)-cne$ApprovalSha256-or[string]$a.schema-cne'evomind.g21_hpc_asset_probe_runtime_deployment_approval.r121.v1'-or[string]$a.status-cne'approved_for_single_runtime_transaction'-or[string]$a.deployment_id-cne$TransactionId-or[string]$a.run_id-cne$fixedRun-or[string]$a.allocation-cne$fixedAllocation-or[string]$a.candidate.installed_runtime_tree_sha256-cne$candidateTreeSha-or[string]$a.candidate.packaged_tools_sha256-cne$packagedToolsSha-or[string]$a.baseline.zip_sha256-cne$baselineZipSha-or[string]$a.baseline.runtime_tree_sha256-cne$baselineTreeSha-or[string]$a.baseline.manifest_sha256-cne$baselineManifestSha-or[string]$a.deployer.remote_runner_sha256-cne(Sha $PSCommandPath)){throw 'R121_APPROVAL_REJECTED'};foreach($x in @([pscustomobject]@{p=$archive;s=[string]$a.candidate.sha256},[pscustomobject]@{p=$sourceManifestPath;s=[string]$a.candidate.source_manifest_sha256},[pscustomobject]@{p=$buildResultPath;s=[string]$a.candidate.build_result_sha256},[pscustomobject]@{p=$receiptPath;s=[string]$a.verification.test_receipt_sha256})){if((Sha $x.p)-cne$x.s){throw 'R121_INPUT_HASH_REJECTED'}};$a}
function Candidate([object]$Approval){if(Test-Path -LiteralPath $stage){throw 'R121_STAGE_EXISTS'};Expand-Archive -LiteralPath $archive -DestinationPath $stage;AssertNoReparse $stage;$m=ReadObj (Join-Path $stage 'hpc-asset-probe-runtime-r121-manifest.json') 'R121_MANIFEST';if((Sha (Join-Path $stage 'hpc-asset-probe-runtime-r121-manifest.json'))-cne(Sha $sourceManifestPath)-or[string]$m.schema-cne'evomind.g21_hpc_asset_probe_runtime.r121.v1'-or[string]$m.candidate_runtime_tree_sha256-cne$candidateTreeSha-or[string]$m.packaged_tools_sha256-cne$packagedToolsSha-or[int]$m.candidate_runtime_file_count-ne32-or[int]$m.changed_file_count-ne1-or[int]$m.unchanged_file_count-ne31-or[bool]$m.production_deployable-or[bool]$m.production_deployed){throw 'R121_MANIFEST_REJECTED'};$declared=@{};foreach($e in @($m.files)){$p=[string]$e.path;if($p-cnotmatch'^evomind_runtime/[A-Za-z0-9_]+\.py$'-or$declared.ContainsKey($p)){throw 'R121_MANIFEST_ENTRY_REJECTED'};$declared[$p]=$e};$actual=@(Get-ChildItem -LiteralPath $stage -Recurse -File -Force|ForEach-Object{$_.FullName.Substring($stage.Length+1).Replace('\','/')}|Where-Object{$_-ne'hpc-asset-probe-runtime-r121-manifest.json'});if($declared.Count-ne32-or$actual.Count-ne32-or@($actual|Where-Object{-not$declared.ContainsKey($_)}).Count){throw 'R121_FILESET_REJECTED'};foreach($p in $declared.Keys){$f=Join-Path $stage $p.Replace('/','\');$e=$declared[$p];if((Get-Item -LiteralPath $f).Length-ne[long]$e.bytes-or(Sha $f)-cne[string]$e.sha256){throw 'R121_FILE_HASH_REJECTED'}};$c=Join-Path $stage 'evomind_runtime';$t=Tree $c;if($t.file_count-ne32-or$t.sha256-cne$candidateTreeSha){throw 'R121_TREE_REJECTED'};[ordered]@{path=$c;tree=$t;manifest=$m}}

if((Test-Path -LiteralPath $resultPath)-or(Test-Path -LiteralPath $errorPath)){throw 'R121_RESULT_EXISTS'}
$mutex=[Threading.Mutex]::new($false,'Global\EvoMind-Byoa-V12-Deployment');$owned=$false;$backup=$null;$candidate=$null;$bundleCandidate=$null;$targetBackedUp=$false;$serviceStopped=$false;$databaseBackup=$null;$boundaryBefore=$null
try{$owned=$mutex.WaitOne([TimeSpan]::FromSeconds(10));if(-not$owned){throw 'R121_DEPLOYMENT_LOCKED'};$approval=Inputs;$candidate=Candidate $approval;$preLoopback=Health 'http://127.0.0.1:8088/api/healthz';$prePublic=Health 'https://evomind.zhjjq.tech/api/healthz';$managedBefore=Managed;$runBefore=RunGate;$goalBefore=GoalGate;$toolBefore=ToolGate;$current=Tree $target;if($current.file_count-ne32-or$current.sha256-cne$baselineTreeSha){throw 'R121_CURRENT_RUNTIME_NOT_R120'};$webRoot=[string](RuntimeInfo).config.web_runtime_root;$webBefore=Tree $webRoot;$boundaryBefore=Boundary;InvokeManaged Stop|Out-Null;$serviceStopped=$true;AssertStopped;$backup=Join-Path "$root\backups" ('pre-r121-hpc-asset-probe-'+[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssZ')+'-'+$TransactionId);New-Item -ItemType Directory -Path (Join-Path $backup 'original')|Out-Null;$databaseBackup=BackupDb $backup (RuntimeInfo).config;Copy-Item -LiteralPath $approvalPath -Destination (Join-Path $backup 'approval.json');WriteJson (Join-Path $backup 'backup-manifest.json') ([ordered]@{schema='evomind.g21_hpc_asset_probe_runtime_backup.r121.v1';transaction_id=$TransactionId;approval_sha256=$ApprovalSha256;old_runtime_tree=$current;new_runtime_tree=$candidate.tree;database=$databaseBackup;boundary=$boundaryBefore});$bundleCandidate=Join-Path $bundleRuntime "evomind_runtime.$TransactionId.stage";Move-Item -LiteralPath $candidate.path -Destination $bundleCandidate;Move-Item -LiteralPath $target -Destination (Join-Path $backup 'original\evomind_runtime');$targetBackedUp=$true;Move-Item -LiteralPath $bundleCandidate -Destination $target;& $seal|Out-Null;$installed=Tree $target;if($installed.file_count-ne32-or$installed.sha256-cne$candidateTreeSha){throw 'R121_INSTALLED_TREE_REJECTED'};SameBoundary $boundaryBefore (Boundary);InvokeManaged Start|Out-Null;$serviceStopped=$false;Health 'http://127.0.0.1:8088/api/healthz'|Out-Null;InvokeManaged Stop|Out-Null;$serviceStopped=$true;AssertStopped;InvokeManaged Start|Out-Null;$serviceStopped=$false;$loopback=Health 'http://127.0.0.1:8088/api/healthz';$public=Health 'https://evomind.zhjjq.tech/api/healthz';$managedAfter=Managed;Assert-Fresh $managedBefore $managedAfter;$runAfter=RunGate;if($runAfter.status-cne$runBefore.status-or$runAfter.last_event_seq-ne$runBefore.last_event_seq){throw 'R121_RUN_CHANGED'};$goalAfter=GoalGate;if(($goalAfter|ConvertTo-Json -Compress)-cne($goalBefore|ConvertTo-Json -Compress)){throw 'R121_GOAL_CHANGED'};$toolAfter=ToolGate;SameBoundary $boundaryBefore (Boundary);$webAfter=Tree $webRoot;if($webAfter.file_count-ne$webBefore.file_count-or$webAfter.sha256-cne$webBefore.sha256){throw 'R121_WEB_CHANGED'};$final=Tree $target;if($final.sha256-cne$candidateTreeSha){throw 'R121_FINAL_TREE_REJECTED'};$payload=[ordered]@{schema='evomind.g21_hpc_asset_probe_runtime_deployment_result.r121.v1';status='installed_and_verified';transaction_id=$TransactionId;approval_sha256=$ApprovalSha256;web_build_id=$fixedWebBuild;pre_loopback=$preLoopback;pre_public=$prePublic;loopback=$loopback;public=$public;managed_before=$managedBefore;managed_after=$managedAfter;run_before=$runBefore;run_after=$runAfter;goal_before=$goalBefore;goal_after=$goalAfter;goal_unchanged=$true;tool_before=$toolBefore;tool_after=$toolAfter;old_runtime_tree=$current;installed_runtime_tree=$final;backup_root=$backup;database_backup=$databaseBackup;web_tree_unchanged=$true;hpc_binding_unchanged=$true;hpc_accessed=$false;gpu_touched=$false;hpc_remote_writes=0;direct_signals_sent=0;other_processes_modified=$false;training_started=$false;hpc_tool_calls=0;managed_service_actions=@('Stop','Start','Stop','Start')};WriteJson $resultPath $payload;$payload|ConvertTo-Json -Depth 30 -Compress}catch{$failure=$_;$rollback='not_required';$rollbackError=$null;if($targetBackedUp){try{if(-not$serviceStopped){InvokeManaged Stop|Out-Null;$serviceStopped=$true;AssertStopped};if(Test-Path -LiteralPath $target){Remove-Item -LiteralPath $target -Recurse -Force};Move-Item -LiteralPath (Join-Path $backup 'original\evomind_runtime') -Destination $target;RestoreDb $backup $databaseBackup;& $seal|Out-Null;InvokeManaged Start|Out-Null;$serviceStopped=$false;Health 'http://127.0.0.1:8088/api/healthz'|Out-Null;$rollback='restored_and_verified'}catch{$rollback='failed';$rollbackError=SafeError $_.Exception.Message}}elseif($serviceStopped){try{InvokeManaged Start|Out-Null;$serviceStopped=$false;Health 'http://127.0.0.1:8088/api/healthz'|Out-Null;$rollback='start_only_recovered'}catch{$rollback='failed';$rollbackError=SafeError $_.Exception.Message}};$safe=SafeError $failure.Exception.Message;WriteJson $errorPath ([ordered]@{schema='evomind.g21_hpc_asset_probe_runtime_deployment_error.r121.v1';status='failed';transaction_id=$TransactionId;approval_sha256=$ApprovalSha256;message=$safe;rollback=$rollback;rollback_error=$rollbackError;hpc_accessed=$false;gpu_touched=$false;hpc_remote_writes=0;direct_signals_sent=0;other_processes_modified=$false});throw}finally{if($owned){try{[void]$mutex.ReleaseMutex()}catch{}};$mutex.Dispose()}
